index-of:
def main(xs, x):
    try:
        return xs.index(x)
    except ValueError:
        return -1

is-sorted:
def main(xs):
    for i in range(len(xs) - 1):
        if xs[i] > xs[i + 1]:
            return False
    return True

all-true:
def main(flags):
    for flag in flags:
        if not flag:
            return False
    return True

longest-run:
def main(xs):
    if not xs:
        return 0
    max_run = 1
    current_run = 1
    for i in range(1, len(xs)):
        if xs[i] == xs[i - 1]:
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 1
    return max_run

has-pair-sum:
def main(xs, target):
    seen = set()
    for x in xs:
        if target - x in seen:
            return True
        seen.add(x)
    return False

merge-sorted:
def main(xs, ys):
    result = []
    i = j = 0
    while i < len(xs) and j < len(ys):
        if xs[i] <= ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1
    result.extend(xs[i:])
    result.extend(ys[j:])
    return result

digits:
def main(n):
    if n == 0:
        return [0]
    digits = []
    while n > 0:
        digits.append(n % 10)
        n //= 10
    return digits[::-1]

primes-up-to:
def main(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

histogram:
def main(xs, k):
    counts = [0] * k
    for x in xs:
        counts[x] += 1
    return counts

ledger:
def main(start, txs):
    balance = start
    rejected = 0
    for tx in txs:
        if balance + tx >= 0:
            balance += tx
        else:
            rejected += 1
    return (balance, rejected)
